<script setup lang="ts">
import {computed,ref} from 'vue';import {useAppStore,fmt,time} from '../store';import SkillChart from '../components/SkillChart.vue';
const app=useAppStore();const b=computed(()=>app.data?.benchmark);const onlyGap=ref(false);const rows=computed(()=>b.value?.rows.filter(r=>!onlyGap.value||!r.target_met)??[]);
async function target(value:string){if(app.data){try{await app.save({...app.data.settings,target_rank:value});}catch(e){app.error=String(e);}}}
</script>
<template><div v-if="!b" class="panel empty"><h2>建立可验证的能力基准</h2><p>当前没有 Benchmark 配置。支持 Viscose S2 Easier 结构及自定义等级、分类、门槛和别名。</p><p class="muted">未附带未经确认的 Viscose 分数门槛。请从可靠来源核对后导入 JSON。</p><el-button type="primary" @click="app.page='settings'">导入 Benchmark JSON</el-button></div><template v-else><div class="toolbar"><div><span class="eyebrow">{{b.config.version}} / {{b.config.difficulty}}</span><h2>{{b.config.name}}</h2></div><span class="push-right muted">目标等级</span><el-select :model-value="b.target" @change="target" style="width:180px"><el-option v-for="r in b.config.ranks" :key="r" :label="`${r} Complete`" :value="r"/></el-select></div><section class="panel"><div class="panel-heading"><h3>Complete 进度</h3><span class="muted">以各场景历史最高成绩达标计算 · 包含未训练场景</span></div><div class="rank-grid"><div v-for="c in b.complete" :key="c.rank" class="rank-card"><span>{{c.rank}}</span><strong>{{c.reached}}<small>/ {{c.total}}</small></strong><el-progress :percentage="c.reached/c.total*100" :show-text="false"/><p>{{c.reached===c.total?'Complete ✓':`还有 ${c.total-c.reached} 个场景`}}</p></div></div><p class="muted small">当前各等级场景数：<span v-for="(n,r) in b.rank_counts" :key="r">{{r}} {{n}}　</span></p></section><div class="two-col"><section class="panel"><h3>日常能力分布</h3><SkillChart :benchmark="b"/><p class="muted small">每场景最近最多10次中位数 → 等级区间归一化 → 场景等权平均。完整覆盖前，强弱关系仅供观察。</p></section><section class="panel"><h3>大类分析</h3><div v-for="c in b.categories" :key="c.name" class="skill-row"><div><strong>{{c.name}}</strong><small>{{c.covered}}/{{c.total}} 场景 · {{c.runs}} 次 · {{c.confidence}}</small><small>最值得观察：{{c.weakest_subcategory??'数据不足'}} · 相对个人大类均值 {{fmt(c.relative,2)}}</small></div><b>{{fmt(c.mean,2)}}</b></div></section></div><section class="panel"><div class="panel-heading"><h3>场景达标与下一等级</h3><el-switch v-model="onlyGap" active-text="只看目标差距"/></div><el-table :data="rows"><el-table-column prop="name" label="配置场景" min-width="250"/><el-table-column label="分类" min-width="160"><template #default="{row}">{{row.category}}<small class="block muted">{{row.subcategory}}</small></template></el-table-column><el-table-column label="最高等级" width="145"><template #default="{row}">{{row.best?.rank??(row.count?'未达首级':'未训练')}}</template></el-table-column><el-table-column label="中位数 / PB" width="150"><template #default="{row}">{{fmt(row.median10)}} / {{fmt(row.pb)}}</template></el-table-column><el-table-column label="下一等级进度(PB)" min-width="200"><template #default="{row}"><template v-if="row.best"><span>{{row.best.next_rank??'已达最高级'}} · {{fmt(row.best.progress*100)}}%</span><el-progress :percentage="row.best.progress*100" :show-text="false"/><small class="muted">下一门槛 {{fmt(row.best.next_score)}}</small></template><span v-else>等待记录</span></template></el-table-column><el-table-column label="目标差距" width="135"><template #default="{row}">{{row.target_met?'已达标':row.pb==null?'未训练':fmt(Math.max(0,row.target_score-row.pb))}}</template></el-table-column><el-table-column label="名称匹配" min-width="180"><template #default="{row}">{{row.matched_names.join(' / ')||'无匹配'}}</template></el-table-column></el-table></section><section class="panel"><h3>子项：最高、均值与最低表现</h3><el-table :data="b.subcategories"><el-table-column prop="name" label="子类别" min-width="240"/><el-table-column label="最高 PB 归一化"><template #default="{row}">{{fmt(row.best,2)}}</template></el-table-column><el-table-column label="中位数归一化均值"><template #default="{row}">{{fmt(row.mean,2)}}</template></el-table-column><el-table-column label="中位数归一化最低"><template #default="{row}">{{fmt(row.lowest,2)}}</template></el-table-column><el-table-column label="覆盖 / 总数"><template #default="{row}">{{row.covered}} / {{row.total}}</template></el-table-column></el-table></section><div class="two-col"><section class="panel"><h3>最近达级记录</h3><div v-for="u in b.upgrades.slice(0,8)" :key="`${u.scenario}-${u.rank}`" class="upgrade"><strong>{{u.scenario}}</strong><span class="accent">{{u.rank}}</span><small>{{time(u.timestamp)}}</small></div><p v-if="!b.upgrades.length" class="muted">还没有达级记录。</p></section><section class="panel"><h3>尚未匹配的导入场景</h3><p class="muted small">在设置的 JSON 编辑器中为配置场景添加 aliases。名称只按大小写与空白规范匹配，不自动模糊归类。</p><div class="chips"><span v-for="n in b.unmatched" :key="n">{{n}}</span></div><p v-if="!b.unmatched.length" class="muted">所有已导入场景均匹配。</p></section></div></template></template>
